      "C. Call security immediately because he is shouting.",
      "D. Explain that the consultant is in theatre but you can try to answer his questions.",
      "E. Tell him to leave the office immediately.",
      "F. Interrupt the consultant in theatre to take the complaint.",
      "G. Ignore him until he stops shouting.",
      "H. Apologize for the delay and validate his frustration."
