    "correct": [
      "B. Offer to find a quiet, private room to discuss his concerns.",
      "D. Explain that the consultant is in theatre but you can try to answer his questions.",
      "H. Apologize for the delay and validate his frustration."
    ],
    "explanation": "De-escalation involves moving to a private space (B), acknowledging and validating their frustration (H), and offering realistic help since the requested person is unavailable (D). Calling security immediately (C) is premature if he is just angry and not physically threatening. Telling him to lower his voice (A) can escalate the anger. Interrupting theatre (F) compromises patient safety.",
    "topic": "Communication",
    "subtopic": "Angry Relatives",
    "blueprint_tag": "Professional Dilemmas",
    "clinical_area": "Professional Attributes",
