    "stem": "A 32-year-old woman presents with a painful, red right eye associated with photophobia and watering. Visual acuity is slightly reduced. Fluorescein staining under a blue light reveals a branching 'dendritic' ulcer on the cornea. What is the most appropriate topical treatment?",
